package kz.bekzat.jwt.service;
import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import javax.crypto.SecretKey; import java.nio.charset.StandardCharsets; import java.time.Instant; import java.util.Date;
@Service public class JwtService implements TokenOperations { private final SecretKey key;private final long minutes; public JwtService(@Value("${app.jwt.secret}")String secret,@Value("${app.jwt.access-minutes}")long minutes){key=Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));this.minutes=minutes;} public String createAccessToken(String user,String role){Instant now=Instant.now();return Jwts.builder().subject(user).claim("role",role).issuedAt(Date.from(now)).expiration(Date.from(now.plusSeconds(minutes*60))).signWith(key).compact();} public Claims parse(String token){return Jwts.parser().verifyWith(key).build().parseSignedClaims(token).getPayload();} public boolean isAccessTokenValid(String token){try{parse(token);return true;}catch(Exception e){return false;}} }
